"use client";

import * as React from "react";
import { cn } from "../../lib/utils";

// Slider: generated by UIX from the design system. Same variants and sizes as the Figma component.

const sliderClasses = "skin-quiet block h-6 w-full cursor-pointer appearance-none bg-transparent outline-none [&::-webkit-slider-runnable-track]:h-1-5 [&::-moz-range-track]:h-1-5 [&::-webkit-slider-runnable-track]:rounded-full [&::-moz-range-track]:rounded-full [&::-webkit-slider-runnable-track]:bg-[linear-gradient(to_right,var(--bg-brand)_var(--uix-fill),var(--bg-muted)_var(--uix-fill))] [&::-moz-range-track]:bg-[linear-gradient(to_right,var(--bg-brand)_var(--uix-fill),var(--bg-muted)_var(--uix-fill))] [&::-webkit-slider-thumb]:size-5 [&::-moz-range-thumb]:size-5 [&::-webkit-slider-thumb]:appearance-none [&::-moz-range-thumb]:appearance-none [&::-webkit-slider-thumb]:rounded-full [&::-moz-range-thumb]:rounded-full [&::-webkit-slider-thumb]:border-2 [&::-moz-range-thumb]:border-2 [&::-webkit-slider-thumb]:border-line-brand [&::-moz-range-thumb]:border-line-brand [&::-webkit-slider-thumb]:bg-surface [&::-moz-range-thumb]:bg-surface [&::-webkit-slider-thumb]:-mt-[7px] focus-visible:[&::-webkit-slider-thumb]:ring-3 focus-visible:[&::-webkit-slider-thumb]:ring-line-focus focus-visible:[&::-moz-range-thumb]:ring-3 focus-visible:[&::-moz-range-thumb]:ring-line-focus disabled:cursor-not-allowed disabled:opacity-60";

export interface SliderProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "size" | "value" | "defaultValue" | "onChange"> {
  value?: number;
  defaultValue?: number;
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;
}

const Slider = React.forwardRef<HTMLInputElement, SliderProps>(
  ({ className, min = 0, max = 100, step = 1, value, defaultValue, onChange, style, ...props }, ref) => {
    const [inner, setInner] = React.useState(defaultValue ?? Number(min));
    const current = value ?? inner;
    const span = Number(max) - Number(min);
    const fill = span > 0 ? ((current - Number(min)) / span) * 100 : 0;
    return (
      <input data-slot="slider" data-kind="track"
        ref={ref}
        type="range"
        min={min}
        max={max}
        step={step}
        value={current}
        onChange={(event) => {
          setInner(Number(event.target.value));
          onChange?.(event);
        }}
        style={{ ...style, "--uix-fill": fill + "%" } as React.CSSProperties}
        className={cn(sliderClasses, className)}
        {...props}
      />
    );
  },
);
Slider.displayName = "Slider";

export { Slider };
